function OverseaManageBusinessNode:Awake()
    SetButtonAction(self.Root.gameObject,Bind(self,self.OnBtnRootClick))
end

function OverseaManageBusinessNode:RefreshShow(data)
    if isNull(data.merchant) or not next(data.merchant) then
        KTool.SetActive(self.controller.gameObject,false)
        return
    end

    self.data = data
    --CfUtils.FillText(self.TxtTitle,data.merchant.name)
    local path = CS.ParseUtils.ParsePathNameByData(data.merchant.icon)
    CfUtils.FillImage(self.ImgHead,path)

    local remainTime = data.merchant.remainTime - os.time()
    self:RemoveTimer()
    CfUtils.SetActive(self.CountdownNode.gameObject,remainTime > 0 )
    if remainTime > 0 then
        CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS2(checkNumber(remainTime)))
        if remainTime > 0 then
            self.merchantTimer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
                if count > 0 then
                    CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS2(checkNumber(count)))
                else
                    CfUtils.FillText(self.TxtTime,CfUtils.GetTimeHMS2(checkNumber(0)))
                    CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.merchantTimer)
                    self.merchantTimer = nil
                end
            end, remainTime + 1, false, true)
        end
    end
    KTool.SetActive(self.controller.gameObject,true)
end

function OverseaManageBusinessNode:RemoveTimer()
    if self.merchantTimer then
        CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.merchantTimer)
        self.merchantTimer = nil
    end
end

function OverseaManageBusinessNode:OnBtnRootClick()
    local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
    Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeGoToPosition,{type = "MaidCoffeeBusiness"})
end

function OverseaManageBusinessNode:OnDialogEnd()

end

function OverseaManageBusinessNode:OnDestroy()
    self:RemoveTimer()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageBusinessNode